        if (descriptor.type === 'id') value.kind = kind;
        if (descriptor.type === 'ref') {
            if (descriptor.targets.length !== 1) fail('binding_nominal_unresolved');
            value.type = 'id';
            value.kind = descriptor.targets[0];
