    if (!range || range.start_inclusive !== true || range.end_inclusive !== true) fail('inclusive_range');
    const count = dayOrdinal(range.end) - dayOrdinal(range.start) + 1;
    if (count < 1) fail('range_order');
    return count;
}

module.exports = { parseDate, parseMonth, dayOrdinal, dateFromOrdinal, offsetDate, monthBounds, inclusiveDayCount };

'use strict';
// Pure nominal rule shared by descriptor requirements and the typed pass.
// No compiler/profile imports: the captured TCB dependency graph stays closed
// and acyclic without duplicating this identity classification.
const subjectKinds = Object.freeze({ source: 'source_state', merchant: 'merchant_identity', transfer_pair: 'transfer_identity' });
function claimReferenceKind(claim, segments) {
    const path = segments.join('.');
    if (path === 'subject.ref_id') return subjectKinds[claim.subject.kind] || claim.subject.kind;
    if (/^subject\.(family|person|category|budget)_id$/.test(path)) return segments[1].slice(0, -3);
    if (path === 'subject.person_ids') return 'person';
    return `claim.${path}`;
}
module.exports = { claimReferenceKind };

'use strict';

const { canonicalValue } = require('../kernel/canonicalValue');
const { claimReferenceKind } = require('./claimNominalTypes');
const failures = new WeakMap();
const fail = (code, dependency) => {
    const error = new Error(`claim_requirements_${code}`);
    if (dependency) failures.set(error, Object.freeze({ checker: 'claim_requirements', code,
        fact_key: dependency.fact_key, predicate_ids: Object.freeze([...dependency.predicate_ids]) }));
    throw error;
};
const pathKey = segments => JSON.stringify(segments);
const claimAt = (arg, segments) => pathKey(arg?.claim?.segments) === pathKey(segments);
