{
  "schema_version": 1,
  "contract_id": "consumption_total_v1",
  "metric": "consumption_total",
  "unit": "BRL_minor",
  "stage": "authoring",
  "signature": {
    "context": "explicit_versioned_instrumented_claim",
    "operands": "resolve_roles_from_metric_evaluator_registry",
